#include "MeterPanel.h"
#include "../Theme.h"
void MeterPanel::paint(juce::Graphics& g){const float w=getWidth(),h=getHeight();Theme::label(g,"OUTPUT",{0,0,w,23},16,true,Theme::green);const float vals[]{display[0],rms[0],display[1],rms[1]};for(int i=0;i<4;++i){float x=12+i*27;juce::Rectangle<float> rect{x,38,17,h-52};g.setColour(Theme::bg);g.fillRect(rect);float db=juce::Decibels::gainToDecibels(vals[i],-60.f);float amt=juce::jlimit(0.f,1.f,(db+60.f)/66.f);g.setColour(Theme::green.withAlpha(i==1||i==3?.65f:1.f));g.fillRect(rect.removeFromBottom(rect.getHeight()*amt));g.setColour(Theme::dim);g.drawRect(juce::Rectangle<float>{x,38.f,17.f,h-52.f},1.f);}g.setColour(Theme::text);g.setFont(Theme::font(11));g.drawText("L  RMS    R RMS",0,(int)h-13,(int)w,13,juce::Justification::centred);}
